// 家事开发期关键数据检查；只检真实创建/费用/继任链，不替代最终统一验收。
#include "resident/domains/family/family_model.hpp"
#include <cassert>
#include <iostream>
using namespace hanmo::resident;
// 最小同世界真人夹具直接执行领域和共同原子写口。
int main(){auto common_catalog=std::make_shared<CommonCatalog>();common_catalog->places.insert("hall",{"hall","town",{}});RoleDefinition role;role.id="adopter";role.initial_actor="provider";role.place_id="hall";role.services={"family_adopt"};common_catalog->roles.insert(role.id,role);common_catalog->texts.insert("child_name","阿平");CommonState seed;seed.identity.tick=0;seed.next_instance_id=1;seed.metadata.player_actor_id="guardian";seed.rng.insert("world",{1,1,{}});FamilyCatalog catalog;catalog.enabled=true;catalog.founder_actor_id="guardian";
for(auto id:{"guardian","provider"}){ActorRecord a;a.id=id;a.alive=true;a.available=true;a.hp=100;a.birth_tick=-40*720;a.created_tick=0;a.wallet_id="cash:"+a.id;a.inventory_id="bag:"+a.id;a.location=SettlementLocation{"town","hall"};seed.actors.insert(id,a);seed.request_sequences.insert(id,0);seed.wallets.insert(a.wallet_id,{a.wallet_id,{Owner::Kind::actor,id,{}},100,{}});seed.inventories.insert(a.inventory_id,{a.inventory_id,{Owner::Kind::actor,id,{}},20,0,{}});catalog.prototypes.insert(id,{});}
IdentityPrototype prototype;prototype.attributes={20,20,20,20,20};catalog.prototypes.insert("child_prototype",prototype);FamilyConfig config;config.valid=true;config.prototype_id="child_prototype";config.child_name_key="child_name";config.wallet_id="cash:provider";config.fee=10;config.adoption_ticks=2;config.policy={17,18,18,40,{},{}};catalog.roles.insert("adopter",config);
CommonStore common(std::move(seed),common_catalog);FamilyState family;family.founder_actor_id="guardian";EstateState estates;EstateCatalog ec;InteractionState interaction;InteractionCatalog ic;ic.common=common_catalog;InteractionAccess ia;ia.battle_occupied=[](const auto&){return false;};ia.resolve_location=[&](const StableId& id){return common.actor(id)->location;};ia.role=[](const auto&){return std::optional<RoleAssignmentView>{{"provider",true}};};TaskState tasks;SocialState social;FamilyAccess access;access.interaction=&interaction;access.interaction_catalog=&ic;access.interaction_access=&ia;access.tasks=&tasks;access.military_or_office_pending=[](const auto&,bool){return false;};access.initialize_schedule=[](const auto&,const auto&,bool enabled){assert(!enabled);return common_success();};FamilyCommand command;command.kind="family_adopt";command.context={"hall","provider","adopter"};auto q=preview_family(common,family,catalog,*common_catalog,estates,ec,access,"guardian",command);assert(q.ok&&q.value.cost==10);auto id=common.next_id("action");ActionCoreView action{id.value,"family_adopt","guardian",{"guardian","provider"},0,2};ActionMutation insert;insert.kind=ActionMutation::Kind::insert;insert.action=action;assert(common.apply_action(insert).ok);for(auto person:{"guardian","provider"}){ActorMutation m;m.actor_id=person;m.action_id=action.id;assert(common.apply_actor(m).ok);}assert(start_family_action(common,family,catalog,*common_catalog,estates,ec,access,action,command,q.value).ok);assert(common.wallet("cash:guardian")->balance==100);assert(common.spendable("cash:guardian").value==90);common.state().identity.tick=2;action.remaining_ticks=0;ActionMutation progress;progress.action=action;progress.remaining_ticks=0;assert(common.apply_action(progress).ok);auto complete=finish_family_action(common,family,interaction,social,catalog,*common_catalog,estates,ec,access,action);if(!complete.ok)std::cerr<<complete.error.original.code<<"\n";assert(complete.ok&&complete.value.success==true&&complete.value.actor_id);auto child=*complete.value.actor_id;assert(common.wallet("cash:guardian")->balance==90&&common.wallet("cash:provider")->balance==110);assert(common.actor(child)&&common.wallet("personal:"+child)->balance==0&&common.inventory("bag:"+child)->capacity==20);assert(family.children.find(child)&&validate_family_identity(common,family,catalog,*common.state().actors.find(child)).ok);
for(auto person:{"guardian","provider"}){ActorMutation m;m.actor_id=person;m.action_id="";assert(common.apply_actor(m).ok);}ActionMutation erase;erase.kind=ActionMutation::Kind::erase;erase.action=action;assert(common.apply_action(erase).ok);family.actions.erase(action.id);assert(validate_family(common,family,catalog,*common_catalog,estates,ec).ok);common.state().identity.tick=722;command.kind="family_designate";command.heir_actor_id=child;q=preview_family(common,family,catalog,*common_catalog,estates,ec,access,"guardian",command);assert(q.ok);auto result=apply_family_instant(common,family,estates,catalog,*common_catalog,ec,access,"guardian",command,q.value);assert(result.ok);command.kind="family_retire";q=preview_family(common,family,catalog,*common_catalog,estates,ec,access,"guardian",command);assert(q.ok);result=apply_family_instant(common,family,estates,catalog,*common_catalog,ec,access,"guardian",command,q.value);assert(result.ok&&common.state().metadata.player_actor_id==child);assert(common.wallet("cash:guardian")->balance==0&&common.wallet("personal:"+child)->balance==90);assert(validate_family(common,family,catalog,*common_catalog,estates,ec).ok);std::cout<<"family_development: reserved adoption, unique actor creation, payment and succession passed\n";}
